head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEnableColumn]<br/>Body Column 정보를 사용하여 특정 Column 에 바인딩된 특정 아이템의 비활성화 여부를 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 특정 아이템을 비활성화 하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Body Column 이 inputType='select','checkcombobox','autoComplete' 이고, 아이템이 DataList 로 바인딩된 경우 동작합니다.",
        "columnId(필수) 파라미터로 아이템의 비활성화 정보값이 설정된, Body Column 에 바인딩된 DataList 의 Column ID 를 설정합니다.",
        "enableColumnFalseValue(필수) 파라미터로 아이템의 비활성화 여부에 대한 기준값들을 ',' 로 구분하여 설정합니다.",
        "enableColumnFalseValue(필수) 설정값 사이에 공백이 있으면 해당 공백도 기준값에 포함됩니다.",
        "enableColumnFalseValue(필수) 파라미터값 중 하나가 columnId 파라미터에 설정된 Column 의 값과 일치하는 경우 해당 아이템은 비활성화로 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 인덱스 2(grade) 는 select 컬럼, 아이템 소스 DataList(dlt_grade) 는 enable_info 컬럼 보유. 인덱스 1(memo) 은 숨김(숨김 컬럼 포함 인덱스). enable_info 가 기준값과 일치하면 비활성.\n[절차] columnInfo(인덱스) / columnId(enable_info) / enableColumnFalseValue 선택 후 (setColumnEnableColumn 실행).\n[확인] falseValue 와 일치하는 아이템은 비활성, 나머지는 활성. 비-select 컬럼(인덱스3) 은 미동작. (F, 0 처럼 공백 포함 시 공백도 기준값)."', '', 'label1');

    // select 컬럼 옵션용 DataList (label/value/enable_info) 동적 생성
    //  enable_info : 아이템 비활성화 여부 기준 컬럼. F/0/공백+0 등 falseValue 와 대조됨.
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strGrade += '<w2:column id="enable_info" name="enable_info" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "label": "A등급", "value": "A", "enable_info": "T" },
        { "label": "B등급", "value": "B", "enable_info": "F" },
        { "label": "C등급", "value": "C", "enable_info": "T" },
        { "label": "D등급", "value": "D", "enable_info": "0" },
        { "label": "E등급", "value": "E", "enable_info": " 0" }
    ], false);

    // GridView 와 바인딩할 body DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name": "노트북", "memo": "재고", "grade": "A", "qty": 3 },
        { "name": "모니터", "memo": "재고", "grade": "B", "qty": 5 },
        { "name": "키보드", "memo": "재고", "grade": "C", "qty": 7 },
        { "name": "마우스", "memo": "재고", "grade": "A", "qty": 9 }
    ], false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        editable: "true"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody, index2 는 select 컬럼)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnEnableColumn 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="메모(숨김)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol3" value="등급(select)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="수량(비-select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : memo (text) - setColumnVisible(1,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="120" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    // index 2 : grade (select) - DataList(dlt_grade) 바인딩 itemset -> setColumnEnableColumn 대상
    strTarget += '<w2:column width="160" style="" inputType="select" id="grade" dataList="grade">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="value"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    // index 3 : qty (number) - 비-select 컬럼 -> setColumnEnableColumn 미동작 검증용
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="qty" dataList="qty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(memo, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// select 컬럼의 렌더 아이템(itemArr) 을 읽어 활성/비활성 상태를 문자열로 만든다.
//  편집모드 진입(setEditMode) 후 select.itemArr 로 확인. _disabled===true 인 아이템이 falseValue 일치로 비활성화된 아이템.
scwin.readEnableInfo = function (colIndex) {
    let opt = target1.getCellInfo(colIndex).options;
    if (opt.inputType !== "select") {
        return "[인덱스 " + colIndex + " / " + target1.getColumnID(colIndex) + "] inputType=" + opt.inputType + " -> select/checkcombobox/autoComplete 가 아니므로 동작하지 않음 (아이템 비활성 미적용)";
    }
    let td = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
    target1.setEditMode(td);
    let sel = target1.getCellInfo(colIndex).select;
    let enabled = [];
    let disabled = [];
    if (sel && sel.itemArr) {
        for (let i = 0; i < sel.itemArr.length; i++) {
            let it = sel.itemArr[i];
            if (it._disabled === true) {
                disabled.push(it.label);
            } else {
                enabled.push(it.label);
            }
        }
    }
    return "[인덱스 " + colIndex + " / " + target1.getColumnID(colIndex) + " (select)] 활성 아이템 [" + enabled.join(', ') + "] / 비활성 아이템 [" + disabled.join(', ') + "]";
}

// [실행] setColumnEnableColumn : select 컬럼에 바인딩된 아이템 중 enable_info 값이 기준값과 일치하는 아이템을 비활성화한다.
//  columnInfo(인덱스) / columnId / enableColumnFalseValue 파라미터를 그대로 전달.
scwin.btn_setEnableColumn_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let columnId = par_columnId.getValue();
    let falseValue = par_enableColumnFalseValue.getValue();

    target1.setColumnEnableColumn(columnInfo, columnId, falseValue);

    let msg = "setColumnEnableColumn(" + columnInfo + ", '" + columnId + "', '" + falseValue + "') 실행"
        + "\n-> " + scwin.readEnableInfo(columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
